SELECT p.id AS position_id, t.id AS wallet_trade_id, t.signal_id, t.execution_key, t.side, t.quantity, t.price_usdt, t.decision_price_usdt, t.execution_price_observed_at, t.executed_at, TIMESTAMPDIFF(MICROSECOND, t.execution_price_observed_at, t.executed_at)/1000000 AS fill_age_s, t.gross_amount_usdt, t.fee_usdt, t.cost_basis_usdt, t.realized_pnl_usdt, t.realized_pnl_percent, t.execution_type, t.execution_reason, t.status FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_trade t ON t.symbol = p.symbol AND t.executed_at BETWEEN DATE_SUB(p.opened_at, INTERVAL 5 SECOND) AND DATE_ADD(p.closed_at, INTERVAL 5 SECOND) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, t.executed_at LIMIT 60